CREATE OR REPLACE FUNCTION public.portal_access_current() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path = public AS $$ SELECT NOT EXISTS (SELECT 1 FROM public.portal_members WHERE user_id = auth.uid() AND status = 'revoked') AND (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin') OR EXISTS (SELECT 1 FROM public.portal_members WHERE user_id = auth.uid() AND status IN ('invited','active'))); $$;
REVOKE ALL ON FUNCTION public.portal_access_current() FROM PUBLIC, anon;
GRANT EXECUTE ON FUNCTION public.portal_access_current() TO authenticated, service_role;
DO $$ DECLARE t text; BEGIN FOREACH t IN ARRAY ARRAY['portal_members','portal_profiles','portal_inquiries','portal_activity','portal_documents','portal_document_acknowledgements','entity_onboarding_releases','meeting_polls','meeting_poll_slots','meeting_poll_responses','meeting_poll_notes','meeting_calendar_holds','executive_questions','question_rounds','question_round_responses','question_groups','question_outbound','question_notification_sends','forum_communication_sends','portal_email_sends','portal_email_templates','governance_reviews','leadership_team'] LOOP EXECUTE format('CREATE POLICY "Current portal access required" ON public.%I AS RESTRICTIVE FOR ALL TO authenticated USING (public.portal_access_current()) WITH CHECK (public.portal_access_current())', t); END LOOP; END $$;
CREATE POLICY "Current access for private portal files" ON storage.objects AS RESTRICTIVE FOR ALL TO authenticated USING (bucket_id NOT IN ('member-headshots','member-documents','leadership-photos') OR public.portal_access_current()) WITH CHECK (bucket_id NOT IN ('member-headshots','member-documents','leadership-photos') OR public.portal_access_current());
ALTER TABLE public.leadership_team ADD COLUMN publication_approved_at timestamptz, ADD COLUMN publication_approved_by uuid, ADD COLUMN publication_scope text NOT NULL DEFAULT 'none';
ALTER TABLE public.leadership_team ADD CONSTRAINT leadership_publication_scope_check CHECK (publication_scope IN ('none','portal_members'));
COMMENT ON COLUMN public.leadership_team.publication_scope IS 'Explicit administrator approval for portal-member display only; never public website permission. Linking alone does not approve publication.';
COMMENT ON TABLE public.leadership_settings IS 'Approved intentional exception: generic interface eyebrow, heading, subtext and update metadata only. No member identities, profiles or role/appointment records.';
CREATE POLICY "Leadership publication approval required" ON public.leadership_team AS RESTRICTIVE FOR SELECT TO authenticated USING (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id = auth.uid() AND role = 'admin') OR is_placeholder OR (publication_scope = 'portal_members' AND publication_approved_at IS NOT NULL AND publication_approved_by IS NOT NULL));
ALTER POLICY "Members read own releases" ON public.entity_onboarding_releases USING (EXISTS (SELECT 1 FROM public.portal_members m WHERE m.id = entity_onboarding_releases.member_id AND m.user_id = auth.uid() AND m.status <> 'revoked'));
ALTER POLICY "Members read own questions" ON public.executive_questions USING (EXISTS (SELECT 1 FROM public.portal_members m WHERE m.id = executive_questions.member_id AND m.user_id = auth.uid() AND m.status <> 'revoked'));
ALTER POLICY "Members read own responses" ON public.question_round_responses USING (EXISTS (SELECT 1 FROM public.portal_members m WHERE m.id = question_round_responses.member_id AND m.user_id = auth.uid() AND m.status <> 'revoked'));
ALTER POLICY "Members read polls they are invited to" ON public.meeting_polls USING (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') OR EXISTS (SELECT 1 FROM public.portal_members m WHERE m.user_id=auth.uid() AND m.status <> 'revoked' AND m.id=ANY(meeting_polls.invited_member_ids)));
ALTER POLICY "Invited members read slots" ON public.meeting_poll_slots USING (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') OR EXISTS (SELECT 1 FROM public.meeting_polls p JOIN public.portal_members m ON m.id=ANY(p.invited_member_ids) WHERE p.id=meeting_poll_slots.poll_id AND m.user_id=auth.uid() AND m.status <> 'revoked'));
ALTER POLICY "Members read responses on their polls" ON public.meeting_poll_responses USING (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') OR EXISTS (SELECT 1 FROM public.portal_members m JOIN public.meeting_polls p ON m.id=ANY(p.invited_member_ids) WHERE m.user_id=auth.uid() AND m.status <> 'revoked' AND m.id=meeting_poll_responses.member_id AND p.id=meeting_poll_responses.poll_id));
ALTER POLICY "Members read notes on their polls" ON public.meeting_poll_notes USING (EXISTS (SELECT 1 FROM public.user_roles WHERE user_id=auth.uid() AND role='admin') OR EXISTS (SELECT 1 FROM public.portal_members m JOIN public.meeting_polls p ON m.id=ANY(p.invited_member_ids) WHERE m.user_id=auth.uid() AND m.status <> 'revoked' AND m.id=meeting_poll_notes.member_id AND p.id=meeting_poll_notes.poll_id));
COMMENT ON TABLE public.portal_login_security IS 'DEPRECATED for authentication denial: failed anonymous passwords cannot lock an email. Retained historical records only; provider authenticates and applies supported throttling.';